(window.__quranSurahs=window.__quranSurahs||{})[103]={"nomPhon":"Al-Asr","versets":{"1":{"text":"Par le Temps!","arabe":"وَٱلْعَصْرِ"},"2":{"text":"L'homme est certes, en perdition,","arabe":"إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ"},"3":{"text":"sauf ceux qui croient et accomplissent les bonnes œuvres, s'enjoignent mutuellement la vérité et s'enjoignent mutuellement l'endurance.","arabe":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ"}}};